// This workflow is MANUAL ONLY. Owner must review the AURELIUS campaign first.
// Change all three placeholders; campaign must already be APPROVED in AURELIUS.
const campaignId='REPLACE_APPROVED_CAMPAIGN_ID';
const integrationId='REPLACE_CONNECTED_POSTIZ_CHANNEL_ID';
const scheduledAt='REPLACE_UTC_DATETIME_2026-12-01T12:00:00Z';
if ([campaignId,integrationId,scheduledAt].some(x=>x.startsWith('REPLACE_'))) throw new Error('Owner must specify campaign, Postiz integration and UTC time');
const ms=Date.parse(scheduledAt);
if (!Number.isFinite(ms)||ms<Date.now()+300000) throw new Error('Schedule at least 5 minutes in future');
return [{json:{action:'schedule',campaignId,integrationId,scheduledAt,confirm:'I_APPROVE_SCHEDULE',requestId:'owner-schedule-'+Date.now().toString(36)}}];

const r=$input.first().json;
if (!r.ok || !r.postId) throw new Error('Postiz did not accept scheduled post');
return [{json:{postId:r.postId,channel:r.channel?.name||'',state:'SCHEDULED, NOT YET VERIFIED PUBLISHED',checkedAt:new Date().toISOString()}}];
